"""
kb_stats.py — 知识库统计仪表板

快速查看知识库整体健康状况：页面数、链接图、类型分布、最近更新等。

用法：
  python tools/kb_stats.py              # 完整统计概览
  python tools/kb_stats.py --json       # JSON 格式输出
  python tools/kb_stats.py --top 20     # 列出前 20 个最大/最新页面
  python tools/kb_stats.py --tags       # 标签分布统计
  python tools/kb_stats.py --orphans    # 仅显示孤立页面

数据来源：
  - wiki/.index/meta_full.json（出链、路径、hash）
  - wiki/.index/meta.json（元数据、别名映射）
  - wiki/.index/bm25.json（词表、文档长度）
  - 直接扫描 wiki/ 页面（当索引不存在时）
"""

import os
import re
import sys
import json
import argparse
from collections import defaultdict
from datetime import datetime

try:
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")
except Exception:
    pass

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import kb_lib as K


# ---------------------------------------------------------------- 数据加载

def _load_index_data():
    """加载索引数据，返回 (meta, full, bm) 或回退到直接扫描。"""
    meta = full = bm = None

    if os.path.exists(K.META_PATH):
        with open(K.META_PATH, "r", encoding="utf-8") as f:
            meta = json.load(f)

    if os.path.exists(K.FULL_PATH):
        with open(K.FULL_PATH, "r", encoding="utf-8") as f:
            full = json.load(f).get("pages", {})

    if os.path.exists(K.BM25_PATH):
        with open(K.BM25_PATH, "r", encoding="utf-8") as f:
            bm = json.load(f)

    return meta, full, bm


def _scan_pages_direct():
    """当索引不存在时，直接扫描 wiki 页面获取基本信息。"""
    pages = {}
    for path in K.iter_page_files():
        if K.is_excluded(path):
            continue
        raw = K.read_text(path)
        fm_raw, body = K.split_frontmatter(raw)
        fm = K.parse_frontmatter(fm_raw)
        name = os.path.splitext(os.path.basename(path))[0]
        rel = os.path.relpath(path, K.VAULT).replace("\\", "/")
        size = os.path.getsize(path)
        pages[name] = {
            "type": fm.get("type", ""),
            "summary": fm.get("summary", "") or "",
            "tags": fm.get("tags", []) or [],
            "updated": fm.get("updated", ""),
            "path": rel,
            "size": size,
            "out": K.extract_outlinks(body),
        }
    return pages


# ---------------------------------------------------------------- 统计计算

def compute_stats(meta, full, bm):
    """计算各项统计指标。"""
    stats = {}

    # ---- 使用 full（meta_full.json）作为主要数据源
    if full:
        pages = full
    elif meta:
        # 回退到 meta.json（信息较少）
        pages = {}
        for name, arr in meta.get("pages", {}).items():
            if isinstance(arr, list) and len(arr) >= 6:
                pages[name] = {
                    "type": arr[0], "summary": arr[1], "updated": arr[2],
                    "tags": arr[3], "aliases": arr[4], "terms": arr[5],
                }
        for row in meta.get("sources", []):
            if isinstance(row, list) and len(row) >= 5:
                pages[row[0]] = {
                    "type": "source", "updated": row[1], "summary": row[2],
                    "tags": row[3], "aliases": row[4],
                }
    else:
        # 无索引，直接扫描
        pages = _scan_pages_direct()
        stats["_scanned"] = True

    # ---- 基本计数
    total = len(pages)
    by_type = defaultdict(int)
    for name, p in pages.items():
        t = p.get("type", "unknown")
        by_type[t] += 1

    stats["total_pages"] = total
    stats["by_type"] = dict(by_type)

    # ---- 链接统计（需要 full 数据）
    if full:
        names = set(pages)
        inbound = defaultdict(int)
        outbound_count = {}
        total_edges = 0

        for name, p in pages.items():
            outlinks = p.get("out", [])
            # 归一化链接目标
            valid_out = 0
            for t in outlinks:
                tgt = t.replace("\\|", "|").split("|")[0].split("#")[0].strip()
                tgt = tgt.replace("\\", "").split("/")[-1]
                if tgt.endswith(".md"):
                    tgt = tgt[:-3]   # 页面链接须剥 .md（同 kb_backlinks 修复，2026-10-10）
                if tgt in names and tgt != name:
                    inbound[tgt] += 1
                    valid_out += 1
            outbound_count[name] = valid_out
            total_edges += valid_out

        orphans = [n for n in names if inbound.get(n, 0) == 0]
        avg_in = sum(inbound.values()) / max(1, len(names))
        avg_out = total_edges / max(1, len(names))

        stats["total_edges"] = total_edges
        stats["avg_inbound"] = round(avg_in, 2)
        stats["avg_outbound"] = round(avg_out, 2)
        stats["orphan_count"] = len(orphans)
        stats["orphan_pct"] = round(100 * len(orphans) / max(1, total), 1)

        # 入站最多的页面
        top_inbound = sorted(names, key=lambda n: -inbound.get(n, 0))[:10]
        stats["top_inbound"] = [(n, inbound[n]) for n in top_inbound if inbound[n] > 0]

        # 孤立页面列表
        stats["orphans"] = sorted(orphans)[:30]
    else:
        stats["total_edges"] = "N/A (需要索引)"
        stats["avg_inbound"] = "N/A"
        stats["avg_outbound"] = "N/A"
        stats["orphan_count"] = "N/A"

    # ---- 最近更新
    updated_pages = []
    for name, p in pages.items():
        u = p.get("updated", "")
        if u:
            updated_pages.append((name, str(u)))
    updated_pages.sort(key=lambda x: x[1], reverse=True)
    stats["recent_updates"] = updated_pages[:10]

    # ---- 最大页面（需要文件大小信息）
    if full:
        # 从路径获取文件大小
        sized_pages = []
        for name, p in pages.items():
            path = p.get("path", "")
            if path:
                full_path = os.path.join(K.VAULT, path)
                if os.path.exists(full_path):
                    sized_pages.append((name, os.path.getsize(full_path)))
        sized_pages.sort(key=lambda x: -x[1])
        stats["largest_pages"] = [(n, s) for n, s in sized_pages[:10]]
    else:
        stats["largest_pages"] = []

    # ---- 索引文件信息
    index_files = {}
    for label, path in [("meta.json", K.META_PATH),
                        ("meta_full.json", K.FULL_PATH),
                        ("bm25.json", K.BM25_PATH),
                        ("meta_lite.json", K.META_LITE_PATH)]:
        if os.path.exists(path):
            index_files[label] = round(os.path.getsize(path) / 1024, 1)
    stats["index_files_kb"] = index_files

    # ---- BM25 词表
    if bm:
        stats["vocab_size"] = len(bm.get("df", {}))
        stats["bm25_docs"] = bm.get("n_docs", 0)
    else:
        stats["vocab_size"] = "N/A"
        stats["bm25_docs"] = "N/A"

    # ---- 别名映射
    if meta:
        stats["alias_count"] = len(meta.get("alias_map", {}))
    else:
        stats["alias_count"] = "N/A"

    # ---- 标签分布
    tag_counts = defaultdict(int)
    for name, p in pages.items():
        tags = p.get("tags", [])
        if isinstance(tags, str):
            tags = [tags]
        for tag in tags:
            if tag and str(tag).strip():
                tag_counts[str(tag).strip()] += 1
    stats["tag_counts"] = dict(sorted(tag_counts.items(), key=lambda x: -x[1]))

    return stats


# ---------------------------------------------------------------- 输出格式化

def print_stats(stats, top_n=10):
    """打印统计概览。"""
    print("=" * 56)
    print("  知识库统计仪表板")
    print("=" * 56)

    # 基本信息
    print(f"\n📄 页面总数: {stats['total_pages']}")
    by_type = stats.get("by_type", {})
    for t in sorted(by_type.keys()):
        print(f"   {t:<12}: {by_type[t]}")

    # 链接图
    print(f"\n🔗 链接统计:")
    edges = stats.get("total_edges", "N/A")
    if isinstance(edges, int):
        print(f"   链接边总数 : {edges}")
    else:
        print(f"   链接边总数 : {edges}")
    print(f"   平均入度   : {stats.get('avg_inbound', 'N/A')}")
    print(f"   平均出度   : {stats.get('avg_outbound', 'N/A')}")
    orphan_count = stats.get("orphan_count", "N/A")
    if isinstance(orphan_count, int):
        print(f"   孤立页面   : {orphan_count} ({stats.get('orphan_pct', '?')}%)")
    else:
        print(f"   孤立页面   : {orphan_count}")

    # 索引信息
    print(f"\n📊 索引信息:")
    print(f"   别名条目   : {stats.get('alias_count', 'N/A')}")
    print(f"   词表大小   : {stats.get('vocab_size', 'N/A')}")
    idx_files = stats.get("index_files_kb", {})
    if idx_files:
        print(f"   索引文件:")
        for name, size in idx_files.items():
            print(f"     {name:<18}: {size} KB")

    # 入站最多
    top_in = stats.get("top_inbound", [])
    if top_in:
        print(f"\n🏆 入站链接最多的页面 (TOP {min(top_n, len(top_in))}):")
        for name, count in top_in[:top_n]:
            print(f"   [{count:>2}] {name}")

    # 最近更新
    recent = stats.get("recent_updates", [])
    if recent:
        print(f"\n🕐 最近更新 (TOP {min(top_n, len(recent))}):")
        for name, date in recent[:top_n]:
            print(f"   {date}  {name}")

    # 最大页面
    largest = stats.get("largest_pages", [])
    if largest:
        print(f"\n📦 最大页面 (TOP {min(top_n, len(largest))}):")
        for name, size in largest[:top_n]:
            print(f"   {size // 1024:>3}K  {name}")

    # 标签分布
    tag_counts = stats.get("tag_counts", {})
    if tag_counts:
        print(f"\n🏷️  标签分布 (TOP 20):")
        for tag, count in list(tag_counts.items())[:20]:
            print(f"   [{count:>2}] {tag}")

    print()


def print_orphans(stats):
    """仅输出孤立页面。"""
    orphans = stats.get("orphans", [])
    print(f"孤立页面: {len(orphans)} 个")
    print(f"（入站链接数 = 0 的页面）\n")
    for name in orphans:
        print(f"  - {name}")


def print_tags(stats):
    """详细标签分布。"""
    tag_counts = stats.get("tag_counts", {})
    total = sum(tag_counts.values())
    print(f"标签统计: {len(tag_counts)} 个不同标签, 共 {total} 次使用\n")
    print(f"{'标签':<36} {'次数':>4}  {'占比':>5}")
    print("-" * 50)
    for tag, count in tag_counts.items():
        pct = 100 * count / max(1, total)
        print(f"{tag:<36} {count:>4}  {pct:>4.1f}%")


# ---------------------------------------------------------------- CLI

def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。

    本工具是**统计仪表板**——它的数字会被人当作事实引用，故必须保证
    各计数**内部自洽**（边数 == 出度之和、孤立数 + 非孤立数 == 总数等）。
    这正是本库「计数器本身出错」六次事故的同一风险面。
    """
    ok = True

    # ---- 夹具 1：链式图 A→B，C 孤立 ----
    full = {
        "A": {"type": "concept", "out": ["concepts/B"]},
        "B": {"type": "concept", "out": []},
        "C": {"type": "concept", "out": []},
    }
    st = compute_stats(None, full, None)
    checks = [
        ("total_pages", st.get("total_pages"), 3),
        ("total_edges", st.get("total_edges"), 1),
        ("orphan_count", st.get("orphan_count"), 2),   # B 有入站、A/C 无
        ("by_type.concept", st.get("by_type", {}).get("concept"), 3),
    ]
    for label, got, want in checks:
        mark = "ok" if got == want else "FAIL"
        print(f"  [{mark}] 夹具1 {label} = {got} (期望 {want})")
        ok = ok and got == want

    # ---- 夹具 2：断链与自环都**不得**计入边数 ----
    full2 = {
        "A": {"type": "concept", "out": ["concepts/B", "concepts/不存在", "A"]},
        "B": {"type": "concept", "out": ["A"]},
    }
    st2 = compute_stats(None, full2, None)
    good = st2.get("total_edges") == 2      # A→B, B→A；断链与自环排除
    print(f"  [{'ok' if good else 'FAIL'}] 夹具2 断链+自环不计入边数 -> "
          f"{st2.get('total_edges')} (期望 2)")
    ok = ok and good

    # ---- 夹具 3（反例/边界）：**有页面但无边** 的极小库不得崩溃、也不得报出边 ----
    #    注：刻意**不用** `full={}`——空 dict 为假值，会落进「无索引则直接扫描」分支，
    #    从而去扫真实的 wiki/。此处用一个真实的极小库来钉住边界行为。
    st3 = compute_stats(None, {"Only": {"type": "concept", "out": []}}, None)
    good = (st3.get("total_pages") == 1 and st3.get("total_edges") == 0
            and st3.get("orphan_count") == 1)
    print(f"  [{'ok' if good else 'FAIL'}] 边界 单页无边库 -> "
          f"pages={st3.get('total_pages')} edges={st3.get('total_edges')} "
          f"orphans={st3.get('orphan_count')}")
    ok = ok and good

    # ---- 夹具 4：跨夹具不变量 —— 孤立 + 非孤立 == 总数 ----
    if full:
        stx = compute_stats(None, full, None)
        orphan = stx.get("orphan_count", 0)
        good = 0 <= orphan <= stx.get("total_pages", 0)
        print(f"  [{'ok' if good else 'FAIL'}] 不变量 0 ≤ 孤立数 ≤ 总数 -> "
              f"{orphan} ≤ {stx.get('total_pages')}")
        ok = ok and good

    # ---- 夹具 5：真实索引可算且计数自洽 ----
    meta, realfull, bm = _load_index_data()
    if realfull:
        sr = compute_stats(meta, realfull, bm)
        tp = sr.get("total_pages", 0)
        te = sr.get("total_edges", 0)
        oc = sr.get("orphan_count", 0)
        good = tp > 0 and te >= 0 and oc <= tp
        print(f"  [{'ok' if good else 'FAIL'}] 真实索引自洽 -> "
              f"{tp} 页 / {te} 边 / {oc} 孤立")
        ok = ok and good
    else:
        print("  [info] 无 meta_full.json，跳过真实索引检查")

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(
        description="知识库统计仪表板",
        formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--json", action="store_true", help="JSON 格式输出")
    ap.add_argument("--top", type=int, default=10, help="列出前 N 项（默认 10）")
    ap.add_argument("--tags", action="store_true", help="详细标签分布")
    ap.add_argument("--orphans", action="store_true", help="仅显示孤立页面")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    meta, full, bm = _load_index_data()

    if not meta and not full:
        print("[!] 索引不存在，直接扫描 wiki 页面...", file=sys.stderr)

    stats = compute_stats(meta, full, bm)

    if args.json:
        # JSON 输出：转换不可序列化的值
        out = {}
        for k, v in stats.items():
            if isinstance(v, list):
                out[k] = v
            elif isinstance(v, dict):
                out[k] = v
            else:
                out[k] = v
        print(json.dumps(out, ensure_ascii=False, indent=2))
        return 0

    if args.orphans:
        print_orphans(stats)
        return 0

    if args.tags:
        print_tags(stats)
        return 0

    print_stats(stats, top_n=args.top)

    # 提示
    if stats.get("_scanned"):
        print("💡 提示: 运行 `python tools/kb_build_index.py` 构建索引以获取完整统计。")

    return 0


if __name__ == "__main__":
    sys.exit(main())
